+using System;
+using System.Threading.Tasks;
+using Features;
+using Xunit;
+
+public class FeatureFlagsScopedEnvTests
+{
+    [Fact]
+    public void InnerScope_RestoresOuter_EvenWhenInnerThrows()
+    {
+        using (FeatureFlags.OverrideEnvironment(_ => "true"))
+        {
+            Assert.True(FeatureFlags.IsEnabled("X"));
+            try
+            {
+                using (FeatureFlags.OverrideEnvironment(_ => "false"))
+                {
+                    Assert.False(FeatureFlags.IsEnabled("X"));
+                    throw new InvalidOperationException("boom");
+                }
+            }
+            catch (InvalidOperationException)
+            {
+            }
+
+            Assert.True(FeatureFlags.IsEnabled("X"));
+        }
+    }
+
+    [Fact]
+    public async Task ParallelFlows_DoNotLeakProvider()
+    {
+        async Task<bool> Flow(string v)
+        {
+            using (FeatureFlags.OverrideEnvironment(_ => v))
+            {
+                await Task.Yield();
+                await Task.Delay(1);
+                return FeatureFlags.IsEnabled("ANY");
+            }
+        }
+
+        var results = await Task.WhenAll(Flow("true"), Flow("false"), Flow("true"));
+        Assert.Equal(new[] { true, false, true }, results);
+    }
+
+    [Fact]
+    public void DefaultPath_ReadsRealEnvironment()
+    {
+        Assert.False(FeatureFlags.IsEnabled("DEFINITELY_NOT_SET_" + Guid.NewGuid().ToString("N")));
+    }
+}

steps.message:
FeatureFlags.IsEnabled keeps its public static signature, so I preserved `public static class FeatureFlags` and `IsEnabled(string name)` and added a scoped environment seam behind it. The obstacle is the direct `Environment.GetEnvironmentVariable` call, which would otherwise force tests to mutate real process environment variables; that is process-global state and breaks parallel isolation. Because the API cannot take a parameter, I route the lookup through an ambient provider held in an `AsyncLocal<Func<string, string?>?>`.

```csharp
public static class FeatureFlags
{
    private static readonly AsyncLocal<Func<string, string?>?> s_provider = new();

    private static Func<string, string?> Provider =>
        s_provider.Value ?? Environment.GetEnvironmentVariable;

    public static bool IsEnabled(string name) =>
        string.Equals(Provider(name), "true", StringComparison.OrdinalIgnoreCase);

    public static IDisposable OverrideEnvironment(Func<string, string?> provider)
    {
        var previous = s_provider.Value;   // capture what was active in THIS scope
        s_provider.Value = provider;
        return new Restore(() => s_provider.Value = previous);
    }

    private sealed class Restore(Action onDispose) : IDisposable
    {
        public void Dispose() => onDispose();
    }
}
```

When no override is active the provider is `Environment.GetEnvironmentVariable`, so production still reads the real environment and keeps the case-insensitive comparison against "true". The override flows across `await` through `AsyncLocal` and restores the previous provider on disposal, so nested overrides unwind like a stack.

The exception-safety guarantee comes from placing the restore in the disposal path: a `using` scope (or an explicit try/finally) restores the previous provider even when code inside the inner scope throws, because `Dispose` runs during unwinding. Tests prove this and stay deterministic without mutating process state:

- A nested-with-throw test opens an outer override returning "true" for a flag, then inside a `using` inner override returning "false" it invokes code that throws; it catches the exception and asserts that after the inner scope unwinds `IsEnabled` again reports the outer value, proving restoration survives an exception rather than leaking the inner provider or clearing the slot.
- A parallel test runs several `Task.Run` flows, each with its own in-memory provider dictionary, awaits `Task.WhenAll(...)`, and asserts each flow observes only its own flag values, proving isolation with no environment mutation.
- A default-path test asserts an unset variable yields false through the real lookup, confirming the production default is intact.

Built the production project, then ran `dotnet test fixtures/static-feature-flags/tests/StaticFeatureFlags.Tests.csproj`; all tests pass and no test writes a real environment variable.
